  // -----------------------------------------------------------------
  async validateUser(username: string, password: string): Promise<any> {
    const user = await this.userService.findOne({ where: { username } });
    if (!user || !bcrypt.compareSync(password, user.password)) {
      return null;
    }
    return user;
  }

  // -----------------------------------------------------------------
  // 2️⃣ Login → gera token 📝
  // -----------------------------------------------------------------
  async login(req: Request): Promise<{ access_token: string }> {
    const { username, password } = req.body;
    const user = this.validateUser(username, password);
    if (!user) {
      throw new BadRequestException('Credenciales inválidas');
    }

    const payload = { username: user.username, sub: user.userId };
    return {
      access_token: this.jwtService.sign(payload),
    };
  }

  // -----------------------------------------------------------------
  // 3️⃣ Guard passaporte ja autenticado (re‑uso) 👍
  // -----------------------------------------------------------------
  get currentUser(): any {
    // Provide JWT payload for controllers/hooks
  }

  // -----------------------------------------------------------------
  // 4️⃣ Refresh token (opcional)
  // -----------------------------------------------------------------
  async refreshToken(token: string, refreshSecret: string): Promise<string> {
    const payload: { sub: string } = this.getJwtPayload(token);
    const newExpiration = Date.now() + 12 * 60 * 1000; // 12h

    const payloadUpdated: { sub: string, otp: number } = {
      sub: payload.sub,
      otp: this.userService.generateOneTimePassword(user: payload),
      // you can hash it before sending or just generate new randomly
    };

    return this.jwtService.sign(payloadUpdated, {
      expiresIn: '12h',
    } as any);
  }
}
```

