### 3.6. Middleware de Auth(usernameGuard.js)

```ts
export default {
  name: 'authication',
  async beforeEach((to, from, next) => {
    try {
      // Load the JWT if present
      const token = from.cookies.get('auth_token');

      if (token && token.value) {
        // -----------------------------------------------------------------
        // Here we call the backend to verify token (or fetch from session)
        // -----------------------------------------------------------------
        await this.authFetch.getAccessToken();
        session.isAuthenticated = true;
        // Pass user data to router
        session.set('userId', token.value);
      } else {
        // no token → authorized but not logged in
        // redirect to login or show login page
        const isLoginPath = to.path.startsWith('/login');
        if (!isLoginPath) {
          // not authorized
        // console.log('authentication middleware aborting', ...
        next();
    } else {
      console.log('Unauthorized request');
      next(new VictorianUrlError('Unauthorized access', '/login'));
    }
  },
  // run even if route changes, necessary for push history
  async afterEach((to, from, next) => {
    if (!session.isAuthenticated) {
      // redirect to /login on logout
      session.push('/login');
    } else {
      // continue normal
    }
    next();
  }),
};
```

