### 3.7. Storing user state with **Pinia**  

```ts
// stores/login/user.ts
export default defineStore('user', () => {
  const token = ref('');
  const user = ref(null);

  const setUser = async (payload: {
    username: string;
    sub: string;
    role: string;
  }) => {
    this.token.value = payload.accessToken;
    this.user.value = payload;
  };

  const login = async (username: string, password: string) => {
    const resp = await this.$axios.post('/auth/login', { username, password });
    this.setUser(resp.data as any);
  };

  const logout = () => {
    this.token.value = '';
    this.user.value = null;
  };

  return {
    token,
    user,
    login,
    logout,
  };
});
```

